/**
 * A formiga do deserto — a ida torta, a volta reta.
 *
 * A Cataglyphis sai do ninho vagando atrás de comida e volta em LINHA RETA, sem
 * refazer o caminho: ela vai somando cada passo enquanto anda. O puzzle pede que
 * o investigador MIRE a seta, e a cena é o que dá sentido a isso — ela desenha os
 * dois trajetos no mesmo mapa, a ida quebrada em segmentos e a volta como uma
 * flecha só.
 *
 * O mapa se ajusta ao que existe: os passos vêm do config, e a seta pode apontar
 * para qualquer lado enquanto o investigador procura. O enquadramento é
 * recalculado a cada quadro para nada sair da tela.
 */

import { criarCanvas2d } from '../../../viz/canvas2d.ts';
import {
  disco,
  type EstadoDaViz,
  etiqueta,
  infoDe,
  limitar,
  MATERIAIS,
  numeroDe,
  paleta,
  rodape,
  setaCheia,
  texto,
  titulo,
} from './desenho.ts';
import type { FabricaViz, VizDoPuzzle } from './index.ts';

const AREIA = '#e2cd9e';

function passosDe(bruto: unknown): (readonly [number, number])[] {
  if (!Array.isArray(bruto)) return [];

  const lista: [number, number][] = [];
  for (const item of bruto) {
    if (!Array.isArray(item)) continue;
    const x = Number(item[0]);
    const y = Number(item[1]);
    if (Number.isFinite(x) && Number.isFinite(y)) lista.push([x, y]);
  }
  return lista;
}

const formiga: FabricaViz = (canvas): VizDoPuzzle => {
  let estado: EstadoDaViz = {};
  /** O maior alcance de seta já pedido — a moldura só cresce, nunca encolhe. */
  let alcanceVisto = 0;

  /** A formiga em três bolinhas, apontada na direção em que anda. */
  function bicho(
    ctx: CanvasRenderingContext2D,
    x: number,
    y: number,
    angulo: number,
    tamanho: number,
    tinta: string,
  ): void {
    ctx.save();
    ctx.translate(x, y);
    ctx.rotate(angulo);

    ctx.strokeStyle = tinta;
    ctx.lineWidth = Math.max(1, tamanho * 0.14);
    ctx.lineCap = 'round';
    for (const lado of [-1, 1]) {
      for (const [dx, dy] of [
        [0.2, 1],
        [-0.2, 1.2],
        [-0.7, 1],
      ] as const) {
        ctx.beginPath();
        ctx.moveTo(tamanho * dx, 0);
        ctx.lineTo(tamanho * (dx + dy * 0.5), lado * tamanho * dy);
        ctx.stroke();
      }
    }

    ctx.fillStyle = tinta;
    for (const [dx, r] of [
      [1.1, 0.5],
      [0.15, 0.42],
      [-0.9, 0.62],
    ] as const) {
      ctx.beginPath();
      ctx.ellipse(tamanho * dx, 0, tamanho * r, tamanho * r * 0.82, 0, 0, Math.PI * 2);
      ctx.fill();
    }

    // As antenas.
    ctx.lineWidth = Math.max(0.8, tamanho * 0.1);
    for (const lado of [-1, 1]) {
      ctx.beginPath();
      ctx.moveTo(tamanho * 1.4, lado * tamanho * 0.2);
      ctx.lineTo(tamanho * 2.2, lado * tamanho * 0.7);
      ctx.stroke();
    }
    ctx.restore();
  }

  function desenhar(ctx: CanvasRenderingContext2D, L: number, A: number, t: number): void {
    const cor = paleta();
    const info = infoDe(estado);
    const valores = (estado.valores ?? {}) as Readonly<Record<string, unknown>>;

    const passos = passosDe(info.vetores);
    const sx = numeroDe(info, 'sx', 0);
    const sy = numeroDe(info, 'sy', 0);
    const angulo = (numeroDe(valores, 'ang', 0) * Math.PI) / 180;
    const distancia = numeroDe(valores, 'dist', 0);
    const ok = info.ok === true;
    const tinta = ok ? cor.verde : cor.azul;

    const pontaX = sx + Math.cos(angulo) * distancia;
    const pontaY = sy + Math.sin(angulo) * distancia;

    titulo(ctx, L, A, 'A ida é torta; a volta, uma reta só');

    // ── O enquadramento ───────────────────────────────────────────────────
    // Percorre a ida acumulando, e mede tudo o que precisa caber.
    const trajeto: [number, number][] = [[0, 0]];
    let ax = 0;
    let ay = 0;
    for (const [dx, dy] of passos) {
      ax += dx;
      ay += dy;
      trajeto.push([ax, ay]);
    }

    // A moldura é a CAIXA do que existe, não um círculo em volta do ninho: a
    // ida acontece toda de um lado só, e centrar na origem jogava fora metade
    // do mapa. O alcance da seta entra pelo maior valor já visto, e não pelo
    // atual — assim girar o slider não faz a cena inteira pular de escala.
    alcanceVisto = Math.max(alcanceVisto, distancia);
    const tudo: [number, number][] = [
      ...trajeto,
      [sx, sy],
      [sx - alcanceVisto, sy - alcanceVisto],
      [sx + alcanceVisto, sy + alcanceVisto],
    ];

    const minX = Math.min(...tudo.map(([x]) => x));
    const maxX = Math.max(...tudo.map(([x]) => x));
    const minY = Math.min(...tudo.map(([, y]) => y));
    const maxY = Math.max(...tudo.map(([, y]) => y));

    const x0 = L * 0.06;
    const x1 = L * 0.94;
    const yTopo = A * 0.19;
    const yBase = A * 0.85;
    const escala =
      Math.min((x1 - x0) / Math.max(1, maxX - minX), (yBase - yTopo) / Math.max(1, maxY - minY)) *
      0.82;

    const cx = (x0 + x1) / 2 - ((minX + maxX) / 2) * escala;
    const cy = (yTopo + yBase) / 2 + ((minY + maxY) / 2) * escala;

    const px = (x: number): number => cx + x * escala;
    // O mundo tem y para cima; o canvas, para baixo.
    const py = (y: number): number => cy - y * escala;

    // A areia.
    ctx.fillStyle = AREIA;
    ctx.beginPath();
    ctx.roundRect(x0, yTopo, x1 - x0, yBase - yTopo, 8);
    ctx.fill();
    ctx.strokeStyle = cor.trilho;
    ctx.lineWidth = 1;
    ctx.stroke();

    // ── A ida ─────────────────────────────────────────────────────────────
    ctx.strokeStyle = MATERIAIS.cobre;
    ctx.lineWidth = 2.2;
    ctx.setLineDash([5, 4]);
    ctx.lineJoin = 'round';
    ctx.beginPath();
    for (const [i, p] of trajeto.entries()) {
      if (i === 0) ctx.moveTo(px(p[0]), py(p[1]));
      else ctx.lineTo(px(p[0]), py(p[1]));
    }
    ctx.stroke();
    ctx.setLineDash([]);

    for (const p of trajeto.slice(1, -1)) {
      disco(ctx, px(p[0]), py(p[1]), 3, MATERIAIS.cobre);
    }

    const miudo = limitar(A * 0.03, 8, 11);

    // ── O ninho, com a folga que vale por acerto ──────────────────────────
    ctx.fillStyle = 'rgb(47 143 92 / 16%)';
    ctx.beginPath();
    ctx.arc(px(0), py(0), Math.max(12, Math.hypot(sx, sy) * 0.1 * escala), 0, Math.PI * 2);
    ctx.fill();

    ctx.fillStyle = '#8a6a44';
    ctx.beginPath();
    ctx.moveTo(px(0) - 13, py(0) + 8);
    ctx.lineTo(px(0), py(0) - 11);
    ctx.lineTo(px(0) + 13, py(0) + 8);
    ctx.closePath();
    ctx.fill();
    ctx.fillStyle = cor.texto;
    ctx.beginPath();
    ctx.ellipse(px(0), py(0) + 6, 3.4, 2, 0, 0, Math.PI * 2);
    ctx.fill();
    etiqueta(ctx, 'ninho', px(0), py(0) + 22, miudo, cor.texto, 700);

    // ── A comida, onde a ida termina ──────────────────────────────────────
    disco(ctx, px(sx), py(sy), 6, cor.ouro);
    // O rótulo fica bem acima: com a seta recolhida a formiga pousa em cima da
    // comida, e os dois disputavam o mesmo ponto.
    etiqueta(ctx, 'comida', px(sx), py(sy) - 30, miudo, cor.ouro, 700);

    // ── A seta da volta ───────────────────────────────────────────────────
    if (distancia > 0.05) {
      setaCheia(ctx, px(sx), py(sy), px(pontaX), py(pontaY), tinta, 3);
      bicho(
        ctx,
        px(pontaX),
        py(pontaY),
        Math.atan2(-(pontaY - sy), pontaX - sx),
        Math.max(5, Math.min(10, escala * 0.55)),
        cor.texto,
      );
    } else {
      // Parada em cima da comida, respirando: a cena não fica morta no começo.
      bicho(
        ctx,
        px(sx),
        py(sy),
        Math.sin(t) * 0.3,
        Math.max(5, Math.min(10, escala * 0.55)),
        cor.texto,
      );
    }

    texto(
      ctx,
      `volta: ${Math.round(distancia)} passos   ·   reta de casa: ${Math.round(Math.hypot(sx, sy))} passos`,
      L / 2,
      A * 0.895,
      miudo,
      { cor: cor.fraco, peso: 700 },
    );

    rodape(
      ctx,
      L,
      A,
      ok,
      'Em casa: a seta é a soma de todos os passos ✔',
      'Gire a seta e estique até a ponta pousar no ninho.',
    );
  }

  const base = criarCanvas2d(canvas, {
    aoQuadro: (ctx, { L, A, t }) => desenhar(ctx, L, A, t),
  });

  return {
    aplicar(novo) {
      estado = novo;
    },
    redimensionar: base.redimensionar,
    pausar: base.pausar,
    retomar: base.retomar,
    destruir: base.destruir,
  };
};

export default formiga;
